import{_ as p,a0 as s,w as d,s as a,ao as f,I as o,x as n,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"使用 Find 命令来帮你找到那些需要清理的文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Find 命令来帮你找到那些需要清理的文件 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Find 命令来帮你找到那些需要清理的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Find 命令来帮你找到那些需要清理的文件 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150803 Handy commands for profiling your Unix file systems","title":"使用 Find 命令来帮你找到那些需要清理的文件","tag":"201508","desc":""},"relativePath":"201508/20150803 Handy commands for profiling your Unix file systems.md","filePath":"[post].md"}'),l={name:"201508/20150803 Handy commands for profiling your Unix file systems.md"};function m(u,t,y,g,T,x){const e=s("Link");return d(),a("div",null,[t[13]||(t[13]=f(`<h1 id="使用-find-命令来帮你找到那些需要清理的文件" tabindex="-1">使用 Find 命令来帮你找到那些需要清理的文件 <a class="header-anchor" href="#使用-find-命令来帮你找到那些需要清理的文件" aria-label="Permalink to “使用 Find 命令来帮你找到那些需要清理的文件”">​</a></h1><p><img src="http://images.techhive.com/images/article/2015/07/file-profile-100597239-primary.idge.png" alt="Credit: Sandra H-S"></p><p><em>Credit: Sandra H-S</em></p><p>有一个问题几乎困扰着所有的文件系统 -- 包括 Unix 和其他的 -- 那就是文件的不断积累。几乎没有人愿意花时间清理掉他们不再使用的文件和整理文件系统，结果，文件变得很混乱，很难找到有用的东西，要使它们运行良好、维护备份、易于管理，这将是一种持久的挑战。</p><p>我见过的一种解决问题的方法是建议使用者将所有的数据碎屑创建一个文件集合的总结报告或&quot;概况&quot;，来报告诸如所有的文件数量；最老的，最新的，最大的文件；并统计谁拥有这些文件等数据。如果有人看到五年前的一个包含五十万个文件的文件夹，他们可能会去删除哪些文件 -- 或者，至少会归档和压缩。主要问题是太大的文件夹会使人担心误删一些重要的东西。如果有一个描述文件夹的方法能帮助显示文件的性质，那么你就可以去清理它了。</p><p>当我准备做 Unix 文件系统的总结报告时，几个有用的 Unix 命令能提供一些非常有用的统计信息。要计算目录中的文件数，你可以使用这样一个 find 命令。</p><pre><code>$ find . -type f | wc -l
187534
</code></pre><p>虽然查找最老的和最新的文件是比较复杂，但还是相当方便的。在下面的命令，我们使用 find 命令再次查找文件，以文件时间排序并按年-月-日的格式显示，在列表顶部的显然是最老的。</p><p>在第二个命令，我们做同样的，但打印的是最后一行，这是最新的。</p><pre><code>$ find -type f -printf &#39;%T+ %p\\n&#39; | sort | head -n 1
2006-02-03+02:40:33 ./skel/.xemacs/init.el
$ find -type f -printf &#39;%T+ %p\\n&#39; | sort | tail -n 1
2015-07-19+14:20:16 ./.bash_history
</code></pre><p>printf 命令输出 ％T（文件日期和时间）和 ％P（带路径的文件名）参数。</p><p>如果我们在查找家目录时，无疑会发现，history 文件（如 .bash_history）是最新的，这并没有什么用。你可以通过 &quot;un-grepping&quot; 来忽略这些文件，也可以忽略以.开头的文件，如下图所示的。</p><pre><code>$ find -type f -printf &#39;%T+ %p\\n&#39; | grep -v &quot;\\./\\.&quot; | sort | tail -n 1
2015-07-19+13:02:12 ./isPrime
</code></pre><p>寻找最大的文件使用 ％s（大小）参数，包括文件名（％f），因为这就是我们想要在报告中显示的。</p><pre><code>$ find -type f -printf &#39;%s %f \\n&#39; | sort -n | uniq | tail -1
20183040 project.org.tar
</code></pre><p>统计文件的所有者，使用％u（所有者）</p><pre><code>$ find -type f -printf &#39;%u \\n&#39; | grep -v &quot;\\./\\.&quot; | sort | uniq -c
   180034 shs
     7500 jdoe
</code></pre><p>如果文件系统能记录上次的访问日期，也将是非常有用的，可以用来看该文件有没有被访问过，比方说，两年之内没访问过。这将使你能明确分辨这些文件的价值。这个最后访问（％a）参数这样使用：</p><pre><code>$ find -type f -printf &#39;%a+ %p\\n&#39; | sort | head -n 1
Fri Dec 15 03:00:30 2006+ ./statreport
</code></pre><p>当然，如果大多数最近​​访问的文件也是在很久之前的，这看起来你需要处理更多文件了。</p><pre><code>$ find -type f -printf &#39;%a+ %p\\n&#39; | sort | tail -n 1
Wed Nov 26 03:00:27 2007+ ./my-notes
</code></pre><p>要想层次分明，可以为一个文件系统或大目录创建一个总结报告，显示这些文件的日期范围、最大的文件、文件所有者们、最老的文件和最新访问时间，可以帮助文件拥有者判断当前有哪些文件夹是重要的哪些该清理了。</p><hr>`,23)),o("p",null,[t[1]||(t[1]=n("via: ",-1)),r(e,{href:"http://www.itworld.com/article/2949898/linux/profiling-your-file-systems.html"},{default:i(()=>[...t[0]||(t[0]=[n("http://www.itworld.com/article/2949898/linux/profiling-your-file-systems.html",-1)])]),_:1})]),o("p",null,[t[5]||(t[5]=n("作者：",-1)),r(e,{href:"http://www.itworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...t[2]||(t[2]=[n("Sandra Henry-Stocker",-1)])]),_:1}),t[6]||(t[6]=n(" 译者：",-1)),r(e,{href:"https://github.com/strugglingyouth"},{default:i(()=>[...t[3]||(t[3]=[n("strugglingyouth",-1)])]),_:1}),t[7]||(t[7]=n(" 校对：",-1)),r(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[10]||(t[10]=n("本文由 ",-1)),r(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原创翻译，",-1)),r(e,{href:"https://linux.cn/"},{default:i(()=>[...t[9]||(t[9]=[n("Linux中国",-1)])]),_:1}),t[12]||(t[12]=n(" 荣誉推出",-1))])])}const _=p(l,[["render",m]]);export{h as __pageData,_ as default};
